export type PermissionDecision = 
/**
 * Allow the tool. `updated_input` optionally rewrites the tool input;
 * `None` echoes the original input unchanged.
 */
{ behavior: "allow"; updated_input: JsonValue | null } | 
/**
 * Deny the tool with a human-readable reason.
 */
{ behavior: "deny"; message: string }
/**
 * Permission mode, switched at runtime via `set_permission_mode` (spec §4.5).
 * The wire tokens are exactly these camelCase strings.
 */
export type PermissionMode = "acceptEdits" | "auto" | "bypassPermissions" | "default" | "dontAsk" | "plan"
/**
 * A `can_use_tool` permission prompt surfaced to the UI. The UI answers it via
 * the `answer_permission` command, echoing `request_id`.
 */
export type PermissionRequestPayload = { request_id: string; tool_name: string; tool_use_id: string; input: JsonValue; title: string | null; description: string | null; 
/**
 * CLI-provided suggestions (kept raw).
 */
suggestions: JsonValue; 
/**
 * The path that triggered the check, when the CLI blocked on one (e.g. an edit
 * outside the session's worktree, or outside the allowed directories). Carries
 * the "why" of a prompt that would otherwise read as an ordinary tool request.
 */
blocked_path: string | null; 
/**
 * The CLI's own reason for asking (kept raw — the shape is not contractual).
 * Rendered as free text when it holds a human-readable string.
 */
decision_reason: JsonValue; 
/**
 * Set when the prompt comes from a background sub-agent task rather than the
 * main thread, so the card can attribute it instead of implying the user's own
 * turn is blocked.
 */
agent_id: string | null }
/**
 * The full persisted snapshot the UI hydrates from at boot.
 */
export type PersistedState = { repos: RepoRecord[]; conversations: ConversationRecord[]; 
/**
 * Stable id of the conversation that was active when last persisted.
 */
active_id: string | null }
/**
 * Real plan-usage snapshot: the two account-wide subscription windows, each with a fill %,
 * plus any model-scoped caps. A window is `None` when the endpoint did not report it.
 * `Deserialize` so it can ride the Codex `session_codex_plan_usage` event (the event bus
 * round-trips its payload) — the Codex backend reuses this exact shape for its rate-limit push.
 */
export type PlanUsage = { five_hour: UsageWindow | null; seven_day: UsageWindow | null; 
/**
 * Caps that apply to ONE model rather than the whole account (e.g. Fable's weekly
 * allowance), read from the `limits[]` array — the only place they appear. Empty when
 * the plan has none. `serde(default)` so an older/foreign payload (a Codex push, which
 * has no such concept) still deserializes.
 */
scoped?: ScopedUsageWindow[] }
/**
 * Everything ONE plugin provides — for the per-plugin explorer (click a plugin →
 * browse its skills / sub-agents / MCP servers, like Claude.ai's Customize panel).
 * 
 * Scanned straight from the plugin's install dir REGARDLESS of its enabled state:
 * a disabled plugin must still be browsable. This is why it is a separate read
 * from [`list_extensions`], which only folds an *enabled* plugin's contributions
 * into the active snapshot.
 */
export type PluginContents = { skills: SkillInfo[]; agents: AgentInfo[]; mcp_servers: McpServerInfo[] }
/**
 * One installed plugin relevant to a repository (user-global, or project/local
 * scoped to this repo).
 */
export type PluginInfo = { 
/**
 * `<plugin>@<marketplace>` — the key used in `enabledPlugins`.
 */
id: string; name: string; marketplace: string; version: string | null; description: string | null; enabled: boolean; scope: ExtScope; 
/**
 * A PROVEN update: the marketplace's version is known and differs from the
 * installed one (see [`compute_update`]). Only as fresh as the last `claude
 * plugin marketplace update`; the UI's "Check" button runs that refresh then
 * re-reads. When this is true, [`Self::latest_version`] is always populated.
 */
update_available: boolean; 
/**
 * The upstream commit moved but no version is resolvable on either side, so we
 * can NEITHER prove nor rule out an update — the honest third state.
 * 
 * This is the dominant shape of the official marketplace (278 entries: 225 carry
 * a `source.sha`, only 14 any version), and it is why neither boolean answer
 * works alone: claiming an update produces a badge `claude plugin update` refuses
 * to clear ("already at the latest version"), while claiming currency hides real
 * releases. The UI must say "unknown", not pick a side.
 */
update_unproven: boolean; 
/**
 * The marketplace's human version when it is KNOWN and DIFFERS from the installed
 * one (for a "vX → vY" badge). Always `Some` when `update_available` is true.
 */
latest_version: string | null; 
/**
 * What the plugin provides (scanned from its cache dir), regardless of
 * enabled state — so the UI can show "5 skills" even when toggled off.
 */
skill_count: number; agent_count: number; command_count: number; mcp_count: number }
/**
 * Typed return value of `ping`. Proves React -> Rust (typed command).
 */
export type Pong = { ok: boolean; echo: string; at_ms: number }
/**
 * Subscription rate-limit status, normalized from `rate_limit_event.rate_limit_info`.
 * Carries only what the stream-json protocol exposes: the coarse `status`, the
 * reset time, the window type, and whether overage is active. The precise usage
 * percentage is NOT in the stream (it comes from `GET /api/oauth/usage`).
 */
export type RateLimitSnapshot = { 
/**
 * `"allowed"` (no warning), `"allowed_warning"` (approaching), `"rejected"` (limited), …
 */
status: string | null; 
/**
 * Unix epoch seconds when the current window resets.
 */
resets_at: number | null; 
/**
 * Which window this refers to: `"five_hour"`, `"seven_day"`, …
 */
limit_type: string | null; 
/**
 * `true` while the account is spending overage credits.
 */
using_overage: boolean }
/**
 * Live state of a session's Remote Control ("bridge") — the native Claude Code
 * feature (`/remote-control`) that mirrors this local session onto claude.ai/code
 * and the Claude mobile app so it can be viewed/driven from another device. Toggled
 * via a `remote_control` control request; enabling returns `session_url` (the
 * claude.ai/code link to open). A `connected` bridge can later be DOWNGRADED by a
 * `system/bridge_state` health message (the phone/web dropped, or the bridge
 * errored) — "connected" is only ever reached from the control response, never from
 * `bridge_state`.
 */
export type RemoteControlState = { 
/**
 * `"disconnected"` | `"connecting"` | `"connected"` | `"error"`.
 */
status: string; 
/**
 * The claude.ai/code URL to view & control this session — present when
 * `status == "connected"`. CLAUDE only (its bridge hands back a URL to open).
 */
session_url: string | null; 
/**
 * A rejection / bridge-error message — present when `status == "error"`.
 */
error: string | null; 
/**
 * A device-pairing code to enter in the Codex mobile app to link a device to this
 * remote-controlled session — CODEX only (its `remoteControl/enable` returns no URL;
 * a device is linked via a separate pairing flow). `None` for Claude and when not
 * enabled. The front keeps it visible across status-only pushes while still active.
 */
pairing_code: string | null }
/**
 * A working folder a conversation can be opened in.
 */
export type RepoRecord = { id: string; path: string; 
/**
 * Unix ms timestamp the repo was first added.
 */
added_at: number }
/**
 * An in-flight automatic retry of the current turn's API call.
 */
export type RetryState = { 
/**
 * Which attempt is being made (1-based), when the CLI reports it.
 */
attempt: number | null; 
/**
 * How many attempts the CLI will make in total.
 */
max: number | null; 
/**
 * Short human reason ("Connection error."), when one is available.
 */
reason: string | null }
/**
 * Outcome of a `rewind_files` request — the binary restoring the files it edited
 * since a given user message, from its own checkpoints. Also the shape of a
 * `dry_run` PREVIEW, which reports what *would* change without touching the disk.
 */
export type RewindFilesResult = { 
/**
 * Whether the rewind is possible (dry run) or was performed (real run). `false`
 * with an `error` when file checkpointing is off or no checkpoint covers the message.
 */
can_rewind: boolean; 
/**
 * Absolute paths the rewind would restore / did restore.
 */
files_changed: string[]; 
/**
 * Lines that would be / were added back.
 */
insertions: number; 
/**
 * Lines that would be / were removed.
 */
deletions: number; 
/**
 * Why the rewind is unavailable. The binary answers a SUCCESS control_response even
 * when it refuses, so this is the only signal — never swallow it.
 */
error: string | null }
/**
 * What a rewind removed, returned to the UI.
 */
export type RewindOutcome = { 
/**
 * For a USER-message rewind, the text of the removed prompt so the composer can be
 * re-seeded with it ("go back to this prompt"). `None` for an assistant-message rewind
 * (its response is kept; the user just continues with a new message).
 */
removed_prompt: string | null; 
/**
 * How many transcript lines were dropped. `0` means nothing followed the target —
 * a no-op (the conversation already ended there), and the file is left untouched.
 */
removed_lines: number }
/**
 * A rate-limit window that applies to a NAMED subset of usage (today: a single model) rather
 * than the account as a whole. Kept separate from the two flat windows because its label is
 * data-driven — it comes from the payload, so a renamed or newly added scoped model shows up
 * without a code change.
 */
export type ScopedUsageWindow = { 
/**
 * What the cap is scoped to, as the endpoint names it (`scope.model.display_name`,
 * e.g. `"Fable"`). Displayed verbatim.
 */
label: string; 
/**
 * Which family the cap belongs to (`"weekly"`, `"session"`, …), so the UI can suffix it
 * with the matching window ("7d" / "5h"). `None` when the payload omits it — the UI then
 * shows the bare label rather than guessing a duration.
 */
group: string | null; window: UsageWindow }
/**
 * A search result: which conversation matched, its relevance score, and a short
 * snippet around the first body hit (empty when only title/excerpt matched).
 */
export type SearchHit = { session_id: string; score: number; snippet: string }
/**
 * The Codex backend's subscription rate-limit % (5h + weekly windows) changed. Codex
 * pushes this over the live app-server (`account/rateLimits/updated`) — there is no
 * HTTP/Keychain pull as for Claude — normalized to the SAME `PlanUsage` shape the
 * popover renders. Account-global: the UI keeps ONE Codex plan store (never merged
 * with Claude's Anthropic one) and the `session` here only tags which conversation
 * surfaced it. Windows are sparse (a push may carry only the one that moved), so the
 * front merges onto the last snapshot.
 */
export type SessionCodexPlanUsageEvent = { session: string; usage: PlanUsage }
/**
 * The session's available slash commands (one-shot, at `initialize`). Drives the
 * composer's `/` autocomplete menu.
 */
export type SessionCommandsEvent = { session: string; commands: SlashCommand[] }
/**
 * An extension-inventory invalidation push from a live Codex session — the server
 * noticed its skills / MCP startup status / account changed (`skills/changed`,
 * `mcpServer/startupStatus/updated`, `account/updated`). Carries NO inventory data:
 * the front just invalidates the matching cached queries and refetches through the
 * normal read commands. `area` = `"skills"` | `"mcp"` | `"accounts"`.
 */
export type SessionExtensionsChangedEvent = { session: string; area: string }
/**
 * A normalized conversation item to render (text delta, assistant message,
 * tool result, turn result, …).
 */
export type SessionMessageEvent = { session: string; item: ConversationItem }
/**
 * A `can_use_tool` permission prompt awaiting a decision.
 */
export type SessionPermissionEvent = { session: string; request: PermissionRequestPayload }
/**
 * A pending permission prompt was withdrawn by the CLI and can no longer be
 * answered. The UI drops the card: it otherwise prunes only on a user answer,
 * leaving a dead prompt on screen that silently swallows the next click.
 */
export type SessionPermissionResolvedEvent = { session: string; request_id: string }
/**
 * This session's Remote Control ("bridge") state changed — the ack of a
 * `remote_control` request, or an async `system/bridge_state` health downgrade. The
 * UI maps `session` (handle) → conversation and updates its Remote Control chip
 * (connected + `session_url`, connecting, disconnected, or error).
 */
export type SessionRemoteControlEvent = { session: string; state: RemoteControlState }
/**
 * A session's lifecycle / identity changed.
 */
export type SessionStateEvent = { session: string; state: SessionStatePayload }
/**
 * Coarse lifecycle + identity of a session, emitted whenever it changes.
 */
export type SessionStatePayload = { 
/**
 * `true` while a turn is in flight (between a user message and its `result`).
 */
busy: boolean; 
/**
 * The CLI-assigned conversation id (from `system/init`); enables `--resume`.
 */
session_id: string | null; 
/**
 * The session's CURRENT working directory (from `system/init`). The CLI can
 * move it mid-session when the agent calls `EnterWorktree`/`ExitWorktree`, so
 * the UI reads this — not the static spawn cwd — to show which worktree the
 * conversation is in right now.
 */
cwd: string | null; 
/**
 * Current model id (from `system/init`, refined by the `get_settings`
 * read-back to the resolved id, e.g. `claude-opus-4-8[1m]`).
 */
model: string | null; 
/**
 * Current permission mode (from `system/init` / the `set_permission_mode` ack).
 */
permission_mode: string | null; 
/**
 * Current reasoning-effort level (`low`/`medium`/`high`/`xhigh`). NOT carried
 * by `system/init` — sourced from the `get_settings` control read-back (and the
 * spawn seed). `None` until the first read-back. Drives the effort gauge.
 */
effort: string | null; 
/**
 * Whether "ultracode" (xhigh effort + standing dynamic-workflow orchestration)
 * is active right now. A SEPARATE boolean flag in the CLI, not an effort value.
 */
ultracode: boolean; 
/**
 * Fine-grained activity hint from `system/status` (e.g. `"requesting"`).
 */
activity: string | null; 
/**
 * `true` while waiting on the user to answer a permission prompt.
 */
awaiting_permission: boolean; 
/**
 * The API call for the current turn is being RETRIED after a connection failure
 * (`system/api_error`, which the CLI emits before each automatic retry). Set while
 * a retry is pending, cleared as soon as the turn produces anything else.
 * 
 * Without this the user sees a turn that simply hangs: the CLI recovers on its
 * own, but nothing on screen explains the pause. Carries `attempt`/`max` so the UI
 * can say how far along the recovery is.
 */
retry: RetryState | null; 
/**
 * `true` once the session has ended (the `claude` process exited or was
 * stopped). A final state event with this set lets the UI mark the session
 * dead instead of showing it as live forever.
 */
ended: boolean; 
/**
 * Tokens occupying the model's context window right now: the last model call's
 * `input + cache_creation + cache_read` (from `message_start` live, then the
 * `result`). `None` until the first turn reports usage. Drives the context ring.
 */
context_tokens: number | null; 
/**
 * Size of the active model's context window (from `result.modelUsage[…].contextWindow`,
 * e.g. 200k or 1M for Opus in 1M mode). `None` until a `result` reports it; once
 * known it is kept across turns that omit it. The ring's denominator.
 */
context_window: number | null; 
/**
 * Latest subscription rate-limit snapshot (from `rate_limit_event`). `None` until
 * the CLI emits one. NOTE: the stream only carries status + reset, NOT a usage
 * percentage — that lives behind the `/api/oauth/usage` endpoint (separate task).
 */
rate_limit: RateLimitSnapshot | null }
/**
 * A model-generated few-word summary of the user's LAST message arrived (from a
 * `generate_session_title` control response — same wire as the title, a distinct
 * routing). The UI maps `session` (handle) → conversation and shows it on the Flight
 * Deck card. `seq` is the monotonic per-conversation tag the UI sent: it applies the
 * summary only if `seq` still matches the latest message, so a stale (superseded)
 * response can't overwrite a fresher one.
 */
export type SessionSummaryEvent = { session: string; summary: string; seq: number }
/**
 * A background task (sub-agent / workflow / Monitor / background Bash) was created
 * or changed state. Emitted on every `task_*` transition, keyed (inside the
 * payload) by `task_id`, so the UI tracks the live fleet of background tasks.
 */
export type SessionTaskEvent = { session: string; task: BackgroundTask }
/**
 * A model-generated conversation title arrived (from a `generate_session_title`
 * control response). The UI maps `session` (handle) → conversation and applies the
 * title as the name UNLESS the user set a custom title in the meantime. `seq` is the
 * monotonic per-conversation tag the UI sent: it applies a title only if `seq` is
 * newer than the last applied, so an out-of-order (stale) response can't overwrite a
 * fresher title.
 */
export type SessionTitleEvent = { session: string; title: string; seq: number }
/**
 * One skill available to a repository (file-based or plugin-provided).
 */
export type SkillInfo = { name: string; description: string | null; scope: ExtScope; 
/**
 * Plugin id when plugin-provided; `None` for a user/project file skill.
 */
source: string | null; 
/**
 * Absolute path to the skill's `SKILL.md` — the UI reads it to render a clean
 * markdown view of the skill.
 */
path: string; 
/**
 * Per-skill toggle state. Claude has no per-skill toggle (always `true` there);
 * Codex resolves it from its `[[skills.config]]` entries (Extensions v2).
 */
enabled: boolean }
/**
 * One slash command available in the session, as advertised by the CLI in its
 * `initialize` control response (spec §4.4). The same shape the official VS Code
 * extension consumes to drive its `/` autocomplete menu. `name` carries NO
 * leading slash (e.g. `"compact"`, `"tosse-workflow:pickup"`).
 */
export type SlashCommand = { name: string; 
/**
 * Human-readable description (may be empty). For skills, the CLI prefixes a
 * `(plugin)` / `(dynamic workflow)` source hint.
 */
description: string; 
/**
 * Hint for the command's arguments (e.g. `"<task_id>"`), empty when none.
 */
argument_hint: string }
/**
 * An integrated terminal's shell exited (EOF on the PTY). One-shot, keyed by id;
 * the front marks that terminal done and offers to restart it on re-open.
 */
export type TerminalExitEvent = { id: string }
/**
 * A chunk of output from an integrated terminal's PTY, base64-encoded. Base64
 * (not a `number[]` or a per-chunk lossy string) keeps the byte stream exact and
 * compact — xterm's own decoder reassembles UTF-8 sequences split across chunks.
 * Keyed by the terminal `id` so the front routes it to the right xterm instance.
 */
export type TerminalOutputEvent = { id: string; data: string }
/**
 * Emitted periodically by a Rust timer. Proves Rust -> React (typed event).
 */
export type TickEvent = { seq: number; message: string }
/**
 * The TOSSE connection as the Settings tab shows it. `connected` false with a
 * `signed_out_reason` means we HELD a session and it stopped working (revoked/expired
 * refresh token) — a different story from "never signed in", and the UI says so.
 */
export type TosseAccountStatus = { connected: boolean; name: string | null; email: string | null; 
/**
 * Why a stored session is no longer usable. `None` when simply never connected.
 */
signedOutReason: string | null; 
/**
 * Set when we ARE connected but the identity probe could not run (offline, or the
 * server does not accept Bearer on `/api/v1/*` yet). Never silently swallowed: the
 * card stays "connected" and shows this as the reason the name/email are missing.
 */
identityError: string | null }
/**
 * `GET /api/v1/briefing/morning`, normalised.
 * 
 * ⚠️ What this endpoint deliberately LEAVES OUT: tasks in `Backlog`, `En attente` or
 * `Fait`, and projects that are `Terminé`/`Archivé`. That is the right cut for a "what am
 * I working on" screen — anything else is a targeted `/tasks?project_id=…` away.
 */
export type TosseBriefing = { projects: TosseProject[]; 
/**
 * Paused projects, metadata only (no tasks) — shown recessed rather than hidden, so a
 * project you deliberately parked doesn't vanish from the app that manages it.
 */
pausedProjects: TosseProject[]; 
/**
 * Tasks attached to no project at all. They have no card to live in, so the view gives
 * them their own band instead of dropping them.
 */
generalTasks: TosseTask[] }
/**
 * The client a project hangs off. Nullable in the CRM (a project reaches its client
 * THROUGH a mission, and either link can be missing), which is why the view needs a
 * "no client" band rather than assuming every project has one.
 */
export type TosseClientRef = { id: string; name: string; logoUrl: string | null; 
/**
 * The client's website, when the CRM has one.
 * 
 * Carried for its DOMAIN, not as a link: the CRM's own avatar falls back to that
 * domain's favicon when no logo has been uploaded, which is how most of its clients
 * end up with a mark at all.
 */
website: string | null }
/**
 * Something changed in the TOSSE CRM, per its live SSE feed (`crate::tosse::sse`).
 * 
 * Carries the event KIND only (`"task:updated"`, `"project:archived"`, …) — never the
 * server's payload. The board is aggregated and sorted server-side, so the front treats
 * this as a pure invalidation signal and refetches through the normal read commands; the
 * alternative (patching the cache from here) would duplicate that aggregation in the UI.
 * Already filtered to the domains this app reads — the CRM's broadcast is global and also
 * carries finance / cron / settings traffic that must never reach the webview.
 */
export type TosseCrmEvent = { kind: string }
/**
 * How a local folder came to be linked to a CRM repository.
 */
export type TosseLinkSource = 
/**
 * The user picked it — always wins over any automatic match.
 */
"manual" | 
/**
 * Derived from the folder's `origin` remote.
 */
"remote"
/**
 * The TOSSE live channel's health. Two jobs, and both are load-bearing: the view shows a
 * discreet indicator (a frozen board that claims to be live is the worst outcome), and the
 * transition INTO `live` is the front's cue to refetch wholesale — the server implements no
 * replay, so whatever changed while we were disconnected is only knowable by re-reading.
 */
export type TosseLiveStateEvent = { status: TosseLiveStatus }
/**
 * The live channel's state as published to the UI. `detail` carries the reason whenever
 * there is one — a state that degrades without saying why is a silent error.
 */
export type TosseLiveStatus = { state: LiveState; detail: string | null; 
/**
 * Consecutive failed attempts. Lets the UI distinguish "reconnecting" from "wedged"
 * without parsing prose.
 */
attempts: number; 
/**
 * Connections established since the channel started.
 * 
 * The front's cue to refetch wholesale — and the reason it is a COUNTER rather than a
 * state transition: the server recycles an idle stream every ~12 s, and those recycles
 * deliberately leave the state on `Live` (no flicker), so `live → live` with a bumped
 * counter is exactly the case a transition-based signal would miss.
 */
connections: number }
/**
 * A task the briefing structurally leaves out, plus the project that owns it.
 */
export type TosseOffBoardTask = { 
/**
 * `None` for a task attached to no project at all — the view has a band for those.
 */
project: TosseTaskProject | null; task: TosseTask }
/**
 * A project with the tasks the briefing kept for it.
 * 
 * `tasks` is empty for a paused project: the endpoint reports those by name only, and the
 * view says so instead of pretending the project has nothing left to do.
 */
export type TosseProject = { id: string; name: string; 
/**
 * `"En cours"` / `"En pause"` / `"À démarrer"` — drives the card's state control.
 */
status: string | null; client: TosseClientRef | null; startDate: string | null; dueDate: string | null; tasks: TosseTask[]; 
/**
 * Progress across ALL of the project's tasks, done included — the briefing counts them
 * server-side, so the ring means the same thing here as on the CRM's own page.
 */
taskCount: number; taskDone: number }
/**
 * A project a repository is attached to, trimmed to what the app displays. The CRM models
 * repository↔project as N-N, so this is a list, and it can legitimately be empty.
 */
export type TosseProjectRef = { id: string; name: string; status: string | null }
/**
 * A TOSSE project pinned to one of the app's local folders.
 * 
 * The CRM has no field for a machine path (and a path on this Mac would be
 * meaningless on a colleague's), so the association only ever lives here. Keyed by
 * the PROJECT rather than by the task: every task of a project resolves to the same
 * working folder, so the question is asked once and answered for all of them.
 */
export type TosseProjectRepo = { 
/**
 * The CRM project id. Deliberately NOT a foreign key — it belongs to another
 * system, so nothing local can enforce it.
 */
project_id: string; 
/**
 * FK to [`RepoRecord::id`] — the local folder. Cascades away with the repo.
 */
repo_id: string }
/**
 * One local folder's relationship to TOSSE, as the UI shows it.
 */
export type TosseRepoLink = { repoId: string; 
/**
 * Whether matching actually RAN. False when the CRM's repository list could not be
 * read: the fields below then say nothing about reality.
 * 
 * ⚠️ The distinction that must never collapse: "we looked and found nothing" versus
 * "we could not look". Resolving against an empty list makes the two identical, and
 * the UI then tells the user their repository was deleted — during a 30-second outage,
 * with a destructive button as the only way out.
 */
resolved: boolean; remoteUrl: string | null; 
/**
 * The linked repository. `None` covers three DIFFERENT situations the UI must not
 * blur: nothing matched, the remote matched several (see `ambiguous`), or a manual
 * link points at a repository the CRM no longer returns (see `manual_repository_id`).
 */
repository: TosseRepository | null; source: TosseLinkSource | null; 
/**
 * The id the user pinned. Kept even when it resolves to nothing, so the UI can say
 * "the repository you picked is gone" instead of quietly falling back to unlinked.
 */
manualRepositoryId: string | null; 
/**
 * Candidates when one remote matches SEVERAL CRM repositories. We never pick for the
 * user; the UI offers the choice.
 */
ambiguous: TosseRepository[]; 
/**
 * The folder is not a git repository at all — an ORDINARY situation here (Flight Deck
 * works in folders, not only in clones), so it is not an error: it just means no
 * automatic match is possible, and only a manual pick can associate it.
 */
notARepository: boolean; 
/**
 * Why the folder's remote could not be read — a genuine FAULT only (the folder has
 * vanished, permissions, git missing). `None` on the happy path, when the repository
 * simply has no remote, AND when the folder is not a repository: those are answers.
 */
remoteError: string | null }
/**
 * How each of Flight Deck's folders relates to TOSSE, in one call.
 * 
 * One payload rather than a command per repo: the CRM's repository list is a single
 * request, and matching needs all of it at once.
 */
export type TosseRepoLinksPayload = { 
/**
 * False when no TOSSE session is held. The app is fully usable in that state, so the
 * UI shows nothing at all — and this call costs nothing either (it returns before
 * reading a single git remote).
 */
connected: boolean; 
/**
 * One entry per Flight Deck repo, in the order the store holds them.
 */
links: TosseRepoLink[]; 
/**
 * Every repository the CRM knows, for the manual picker. Empty when `error` is set.
 */
repositories: TosseRepository[]; 
/**
 * Set when we ARE connected but the list could not be read (offline, server error).
 * The links then resolve to nothing, and the UI says why instead of showing a folder
 * as un-associated — which would look like the association was lost.
 */
error: string | null }
/**
 * A repository as TOSSE knows it.
 * 
 * ⚠️ `url` is nullable in the CRM's schema and genuinely absent on a fair share of the
 * rows — a repository with no url can never be matched automatically, which is the whole
 * reason a manual association exists alongside.
 */
export type TosseRepository = { id: string; name: string; url: string | null; host: string | null; 
/**
 * `"Actif"` / `"Archivé"`. Shown, never used to filter: hiding an archived repository
 * would silently break an association the user made deliberately.
 */
status: string | null; 
/**
 * The repo-level context the CRM keeps for agents — Markdown, rendered as-is.
 */
context: string | null; projects: TosseProjectRef[] }
/**
 * A task as the briefing lists it — enough to render a row, and no more.
 * 
 * ⚠️ Deliberately WITHOUT `context`/`content`: the briefing omits them, and pulling every
 * task's Markdown into a list of dozens would cost far more than it shows. The detail
 * panel fetches the full task by id when one is actually opened.
 */
export type TosseTask = { id: string; title: string; 
/**
 * Raw CRM value (`"En cours"`, `"À faire"`, `"Review"`…), shown as-is: it is data, like
 * a project name, and translating it would drift from the CRM read in a browser.
 */
status: string; priority: string | null; 
/**
 * The CRM's `type` field (`"Code"`, `"Admin"`…). Renamed because `type` is a Rust
 * keyword; the wire name is handled by the parser, not by serde.
 */
kind: string | null; assignedTo: string | null; dueDate: string | null; notes: string | null; subtaskCount: number; subtaskDone: number }
/**
 * Everything the detail panel shows for one task (`GET /api/v1/tasks/:id`).
 */
export type TosseTaskDetail = { 
/**
 * The same row shape the list uses, so the panel and the row can't disagree.
 */
task: TosseTask; projectId: string | null; projectName: string | null; 
/**
 * The long-form fields the briefing omits — Markdown, rendered as-is.
 */
context: string | null; content: string | null; subtasks: TosseTask[]; blockedBy: TosseTaskLink[]; blocks: TosseTaskLink[] }
/**
 * A task referenced by another — a blocker, or something this task blocks.
 */
export type TosseTaskLink = { id: string; title: string; status: string | null; 
/**
 * A resolved relation is history, not a live blocker: the panel keeps showing it, but
 * dimmed, so "why was this stuck" stays answerable after the fact.
 */
resolved: boolean }
/**
 * The project a `/api/v1/tasks` row names.
 * 
 * ⚠️ NOT the briefing's [`TosseProject`], and deliberately so: this is all the tasks
 * endpoint knows (no dates, no progress counts, and the client reached through the
 * mission), yet it is enough to BUILD a card for a project the briefing never sends —
 * which is the whole point. A project whose only tasks are off the board has no card in
 * the briefing, so without this its tasks would have nowhere to be rendered and would
 * simply not appear.
 */
export type TosseTaskProject = { id: string; name: string; status: string | null; 
/**
 * ⚠️ Reached through `mission.client` here, where the briefing sends a flat `client`.
 * 
 * The endpoint selects only the client's `id` and `name` (see the CRM's
 * `routes/tasks.ts`), so `logo_url`/`website` are normally absent and the view falls
 * back to initials. Read anyway — if the CRM ever widens that select, the mark appears
 * with no change here.
 */
client: TosseClientRef | null }
/**
 * Why fetching the real usage % failed, typed so the UI can give a tailored next
 * step instead of a dead-end "unavailable". Tagged on `kind` → a clean TS union.
 */
export type UsageError = 
/**
 * No token in the file nor the Keychain (user never logged in via the CLI).
 */
{ kind: "no_token" } | 
/**
 * The Keychain refused access (unsigned app not in the item ACL, or cancelled).
 */
{ kind: "keychain_denied"; detail: string } | 
/**
 * Endpoint rejected the token (HTTP 401/403): expired or revoked.
 */
{ kind: "unauthorized"; status: number } | 
/**
 * The usage endpoint is itself rate-limited (HTTP 429). `retry_after` = seconds
 * from the `Retry-After` header when present. Do NOT hammer it — back off.
 */
{ kind: "rate_limited"; retry_after: number | null } | 
/**
 * Any other non-success HTTP status from the endpoint (carries status + body).
 */
{ kind: "http"; status: number; body: string } | 
/**
 * Network-level failure (DNS, TLS, timeout, offline).
 */
{ kind: "network"; detail: string } | 
/**
 * Response received but unparseable into the expected shape (carries body).
 */
{ kind: "parse"; body: string }
/**
 * One rate-limit window's real fill: `used_percentage` (0–100) + optional reset as a
 * raw timestamp string (ISO 8601, or epoch-seconds digits for the alternate shape) —
 * the frontend converts it with the JS `Date` parser.
 */
export type UsageWindow = { used_percentage: number; resets_at: string | null }
/**
 * What the Settings card needs to render the voice-agent state: whether a key
 * is stored, and a masked hint so the user can tell WHICH key without ever
 * seeing it again.
 */
export type VoiceAgentStatus = { configured: boolean; 
/**
 * e.g. `"sk-…d4f2"` — never more than the tail of the key.
 */
key_hint: string | null }
/**
 * The live state of the voice bridge, as reported to the Settings UI. This is
 * the honest read-back: `running`/`error` reflect what the listener actually
 * did, never what the toggle optimistically hoped (a failed bind must show).
 */
export type VoiceBridgeStatus = { enabled: boolean; running: boolean; port: number; token: string; 
/**
 * The MCP endpoint to paste into the external client, when running.
 */
url: string | null; 
/**
 * Why the server is not running although enabled (bind failure, …).
 */
error: string | null }
/**
 * Live progress of a RUNNING workflow, derived from its append-only
 * `subagents/workflows/<run_id>/journal.jsonl`. The rich manifest (`wf_<id>.json`) is
 * only written when the run FINISHES, so during the run the journal is the sole on-disk
 * source of "how far along are we": one `{"type":"started",…}` per agent spawn and one
 * `{"type":"result",…}` per agent completion.
 * 
 * The counts are derived from [`Self::agents`] (one entry per DISTINCT agent id) rather
 * than from raw line counts, so a re-emitted entry can never inflate the total past the
 * number of agents that actually exist.
 */
export type WorkflowJournal = { 
/**
 * Distinct agents the journal knows about (== `agents.len()`).
 */
started: number; 
/**
 * Agents whose `result` entry has landed.
 */
done: number; 
/**
 * Every agent, in first-seen (spawn) order. Lets the UI show the EXACT in-flight
 * set — and drill into a running agent's incrementally-written transcript — instead
 * of only a launched/done tally.
 */
agents: WorkflowJournalAgent[] }
/**
 * One agent of a running workflow, as the live journal knows it. The journal carries
 * ONLY the agent's id (plus a cache `key` we ignore) — no label, no phase, no metrics:
 * those exist solely in the end-of-run manifest. The id is what matters, because it is
 * the key to that agent's transcript on disk
 * (`subagents/workflows/<run_id>/agent-<agentId>.jsonl`), which the CLI writes
 * INCREMENTALLY — so a still-running agent can be read live.
 */
export type WorkflowJournalAgent = { 
/**
 * Key for [`super::subagents::load_subagent_transcript`].
 */
agentId: string; 
/**
 * Whether a `result` entry closed this agent. `false` = still in flight.
 */
done: boolean }
/**
 * A RUNNING workflow's on-disk journal changed: the fresh per-agent progress of that run
 * ([`crate::supervisor::workflow_watch`]). Keyed by `session_id` (Claude's durable id) +
 * `run_id`, the pair every workflow surface already holds.
 * 
 * `journal: None` with no `error` is the NORMAL early state (the CLI creates the journal
 * with the run's first agent). `error` is set when a journal that EXISTS could not be read —
 * a real failure the UI must surface rather than render as a frozen readout.
 */
export type WorkflowJournalEvent = { session_id: string; run_id: string; journal: WorkflowJournal | null; error: string | null }
/**
 * One phase of a workflow run, from a `workflows/wf_<id>.json` manifest.
 */
export type WorkflowPhase = { title: string; detail: string | null }
/**
 * A workflow run's manifest (`workflows/wf_<id>.json`), the data model behind the
 * `/workflows`-style view. Field names mirror the on-disk camelCase manifest. The
 * dynamic, per-entry-shaped `workflowProgress` and `result` are kept raw
 * ([`Value`]) — the Workflow display task types them.
 */
export type WorkflowRun = { runId: string; taskId: string | null; status: string | null; workflowName: string | null; defaultModel: string | null; durationMs: number | null; agentCount: number | null; totalTokens: number | null; totalToolCalls: number | null; summary: string | null; 
/**
 * `#[serde(default)]` alone covers a MISSING key, but an explicit `"phases":null`
 * would still fail the WHOLE manifest parse (blanking the entire workflow view).
 * `deserialize_null_default` maps null → empty, mirroring the stream structs'
 * `Option` null-tolerance ([`super::protocol::TaskNotificationMsg::usage`]).
 */
phases?: WorkflowPhase[]; 
/**
 * Array of `{type:"workflow_phase"|"workflow_agent", …}` entries — kept raw.
 */
workflowProgress?: JsonValue; 
/**
 * The workflow's final return value — kept raw.
 */
result?: JsonValue }
/**
 * Identity of one worktree of a repository (the cheap, always-listed part).
 * 
 * A repository has exactly one MAIN worktree (the original checkout) plus any
 * number of LINKED worktrees created with `git worktree add`. Each is a
 * separate working directory sharing the same `.git` history — which is what
 * lets several `claude` agents work the same repo in parallel without stepping
 * on each other.
 */
export type WorktreeInfo = { 
/**
 * Absolute path of the worktree's working directory.
 */
path: string; 
/**
 * Short branch name (`refs/heads/` stripped). `None` when detached or bare.
 */
branch: string | null; 
/**
 * Full HEAD commit oid. `None` for the bare entry.
 */
head: string | null; 
/**
 * The repository's MAIN worktree (the first entry `git` lists). The one
 * worktree that can never be removed.
 */
is_main: boolean; 
/**
 * HEAD is detached (no branch checked out).
 */
is_detached: boolean; 
/**
 * Locked via `git worktree lock` (a removal needs `--force`).
 */
is_locked: boolean; 
/**
 * The bare repository entry (has no working tree of its own).
 */
is_bare: boolean }
/**
 * Working-tree status of one worktree (the heavier, on-demand part — one extra
 * `git` call per worktree, so it is fetched lazily by the manager, never for
 * the always-on indicator).
 */
export type WorktreeStatus = { 
/**
 * At least one tracked file has staged or unstaged modifications.
 */
dirty: boolean; 
/**
 * At least one untracked file is present.
 */
untracked: boolean; 
/**
 * Number of entries `git status --porcelain` reports (changed + untracked).
 */
changed_files: number; 
/**
 * Commits ahead of the branch's upstream. `None` when no upstream is set.
 */
ahead: number | null; 
/**
 * Commits behind the branch's upstream. `None` when no upstream is set.
 */
behind: number | null }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
